<header class="page-heading"><div><p class="eyebrow">Acceso al estadio</p><h1>Entradas</h1><p>Compra con tu cuenta o como invitado. La disponibilidad depende del aforo.</p></div><?php if (!empty($canViewSales)): ?><a class="button button-secondary" href="<?= h(url_for('entradas/registro')) ?>">Ver entradas registradas</a><?php endif; ?></header>
<?php if (!empty($errors)): ?><div class="alert" role="alert"><?php foreach ($errors as $error): ?><p><?= h($error) ?></p><?php endforeach; ?></div><?php endif; ?>
<?php if (!empty($success)): ?><p class="notice" role="status"><?= h($success) ?></p><?php endif; ?>
<?php if (!empty($partido)): ?><section class="panel purchase-panel"><div><p class="eyebrow">Partido</p><h2><?= h($partido['equipo_local_nombre'] ?? 'Equipo local') ?> <span class="vs">vs.</span> <?= h($partido['equipo_visitante_nombre'] ?? 'Equipo visitante') ?></h2><p><?= h($partido['fecha_hora'] ?? '') ?> · <?= h($partido['estadio'] ?? '') ?></p><p><strong><?= h($partido['precio_entrada'] ?? '0.00') ?></strong> por entrada · <?= h($partido['disponibles'] ?? '') ?> disponibles</p></div>
    <form method="post" action="<?= h(url_for('entradas/comprar')) ?>" class="purchase-form">
        <?= csrf_field() ?><input type="hidden" name="partido_id" value="<?= h($partido['id']) ?>">
        <label>Nombre del comprador<input name="nombre_comprador" autocomplete="name" value="<?= h($partido['nombre_sesion'] ?? '') ?>"></label>
        <label>Correo de contacto<input type="email" name="email_comprador" autocomplete="email" value="<?= h($partido['email_sesion'] ?? '') ?>"></label>
        <button class="button" type="submit">Comprar una entrada</button>
        <p class="hint">Inicia sesión para asociar la compra a tu cuenta; si continúas como invitado, completa tus datos de contacto.</p>
    </form></section><p class="section-gap"><a class="text-link" href="<?= h(url_for('entradas')) ?>">Ver otros partidos</a></p><?php else: ?><section class="section-gap"><h2>Partidos disponibles</h2><?php if (empty($partidosDisponibles)): ?><p class="empty-state">Todavia no hay partidos creados.</p><?php else: ?><div class="card-list"><?php foreach ($partidosDisponibles as $partidoDisponible): ?><article class="card match-card"><div><h3><?= h($partidoDisponible['equipo_local_nombre'] ?? 'Equipo local') ?> <span class="vs">vs.</span> <?= h($partidoDisponible['equipo_visitante_nombre'] ?? 'Equipo visitante') ?></h3><p><?= h($partidoDisponible['torneo_nombre'] ?? '') ?> · <?= h($partidoDisponible['fecha_hora'] ?? '') ?></p><p><?= h($partidoDisponible['estadio'] ?? '') ?> · <?= h($partidoDisponible['precio_entrada'] ?? '0.00') ?> por entrada</p><p class="muted">Aforo disponible: <?= h($partidoDisponible['disponibles'] ?? 0) ?></p></div><div class="card-actions"><?php if ((int)($partidoDisponible['disponibles'] ?? 0) > 0): ?><a class="button" href="<?= h(url_for('entradas', ['partido_id' => $partidoDisponible['id']])) ?>">Elegir partido</a><?php else: ?><span class="muted">Aforo completo</span><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
